import './Header.css';

interface HeaderProps {
  connected: boolean;
}

export function Header({ connected }: HeaderProps) {
  return (
    <header className="header">
      <span className="logo">engin</span>
      <span
        className="connection-dot"
        style={{ backgroundColor: connected ? 'var(--engin-success)' : 'var(--engin-error)' }}
      />
    </header>
  );
}

.header {
  height: var(--engin-header-height);
  background: var(--engin-bg-secondary);
  border-bottom: 1px solid var(--engin-border);
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 var(--engin-space-md);
  flex-shrink: 0;
}
.logo {
  font-weight: 700;
  color: var(--engin-accent);
  font-size: 18px;
}
.connection-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
}

